-- Temporary demonstration fixtures. NEVER insert them into authentic editorial or member tables.
create table if not exists public.ascend_demo_fixtures(
 kind text not null check(kind in ('hub_project','hub_event','hub_person','hub_portfolio','academy_course','media_item')),
 fixture_id text not null,
 payload jsonb not null,
 created_at timestamptz not null default now(),
 primary key(kind,fixture_id)
);
alter table public.ascend_demo_fixtures enable row level security;
drop policy if exists "Visitors can read clearly labelled demonstration fixtures" on public.ascend_demo_fixtures;
create policy "Visitors can read clearly labelled demonstration fixtures" on public.ascend_demo_fixtures for select to anon,authenticated using(payload->>'demo'='true' or kind='hub_portfolio');
grant select on public.ascend_demo_fixtures to anon,authenticated;
on conflict(kind,fixture_id) do update set payload=excluded.payload;
-- Cleanup: truncate public.ascend_demo_fixtures; optional drop table and grants when production content is ready.
