('academy_course','demo-c1','{"id":"demo-c1","slug":"demo-systems-thinking","title":"Systems Thinking: See the Connections","summary":"DEMO COURSE — Examine feedback loops and the relationships between everyday systems.","discipline":"Philosophy & Science","cover_url":"","published":true,"demo":true,"lessons":[{"id":"demo-l1","title":"Seeing Systems","sequence":1,"content":"DEMO LESSON — A system consists of components and relationships. Consider a garden: soil, moisture, microbes, plants and people all influence one another.","formats":[{"format":"passage","title":"Read: Seeing Systems","body":"A system is more than a collection of parts. Relationships and feedback determine how it behaves. Think of rainfall, soil moisture, roots, microbes and community stewardship. Changing one part changes the rest."},{"format":"interactive","title":"Practice: Spot Feedback","body":"Which is an example of a feedback loop? A) One isolated brick B) Plants improve soil and healthier soil supports more plants C) A static list of names","answer":1,"choices":["One isolated brick","Plants improve soil and healthier soil supports more plants","A static list of names"]}]}],"quiz":[{"prompt":"What matters most in systems thinking?","choices":["Only isolated objects","Interactions and feedback between components","Memorizing names"],"answer":1},{"prompt":"Which is a reinforcing feedback example?","choices":["Healthier soil helps plants that improve soil","A disconnected rock","An unchanging address"],"answer":0}]}'::jsonb),
('academy_course','demo-c2','{"id":"demo-c2","slug":"demo-visual-storytelling","title":"Visual Storytelling Foundations","summary":"DEMO COURSE — Framing, contrast, symbolism and intentional visual sequences.","discipline":"Film & Arts","cover_url":"","published":true,"demo":true,"lessons":[{"id":"demo-l2","title":"Composition & Meaning","sequence":1,"content":"DEMO LESSON — Composition directs attention. Contrast and movement can establish visual hierarchy and mood.","formats":[{"format":"passage","title":"Read: Composition","body":"Consider subject placement, light, negative space and the relationship of foreground and background. A deliberate frame gives the viewer a visual path."},{"format":"video","title":"Sample video exercise","source_url":"https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4","body":"Royalty-free technical playback sample, not an original Ascend Academy lecture."}]}],"quiz":[{"prompt":"What does negative space help establish?","choices":["Separation and visual emphasis","Only audio levels","Frame rate"],"answer":0}]}'::jsonb),
('academy_course','demo-c3','{"id":"demo-c3","slug":"demo-community-ventures","title":"Launching a Community Initiative","summary":"DEMO COURSE — From local problem to practical collaboration.","discipline":"Social Impact","cover_url":"","published":true,"demo":true,"lessons":[{"id":"demo-l3","title":"Define the problem","sequence":1,"content":"DEMO LESSON — Begin with observed needs, speak to the affected community and define a measurable outcome.","formats":[{"format":"passage","title":"Read: Scope and Purpose","body":"A strong initiative begins with listening, defining a clear problem, and inviting collaborators into shared ownership."}]}],"quiz":[{"prompt":"What should come before designing a community solution?","choices":["Assume everyone agrees","Consult the people affected","Create a logo"],"answer":1}]}'::jsonb),
